// Public key for signing tool catalogs (D-178). The private key is kept offline by the founder,
// never enters the repository, and is not stored on any server. When rotating keys, first add the
// new public key and release an app version, then sign with the new private key, and finally remove
// the old public key.

/**
 * Official public keys (base64), generated by the founder on 2026-10-24 using `npm run tools --
 * keygen --print`. Private keys are stored in the founder's password manager (primary) and
 * another location (backup), pasted during signing (`sign --prompt`).
 */
export const TOOL_SIGNING_KEYS: readonly string[] = [
  'L9//DTdHRvM4ria8sp1zaRkvo08FcqNPqMFtf2cN1GE=', // Primary
  'pnxE8rb/OCWHkm+8ZUT2IHdRHtwwfbcAR1Mq9qD5P6I=', // Backup
];

/**
 * Development public key: private key is in the repository (`tools/dev-signing-key.txt`) and
 * anyone can sign with it, so it is trusted only in development builds (`__DEV__`) and `npm run
 * tools -- verify` run with `--dev`.
 */
export const DEV_TOOL_SIGNING_KEY = 'ar/xNDIgr1lk/vL+KkGkt9lcuPgCZs9UFDDMn5Yp9Fw=';

/** Public keys trusted for this run. */
export const trustedToolKeys = (dev: boolean): readonly string[] =>
  dev ? [...TOOL_SIGNING_KEYS, DEV_TOOL_SIGNING_KEY] : TOOL_SIGNING_KEYS;
